#!/usr/bin/env python3
"""Plot the phonon-limited carrier mobilities and scattering rates (generated by paoflow_gen.py).

    python plot_mobility.py [--temperature T] [--experiment FILE]

Reads OUTPUTDIR/mobility/mobility.dat and carrier_scattering.npz written by
mobility.py: the electron and hole mobilities versus temperature (MRTA solid,
SERTA dashed) and the MRTA rates 1/tau_nk of the window states against the
carrier energy from the band edge, at the temperature closest to T.  The
optional experiment file has three columns: T (K), electron and hole
mobilities (cm^2/(V s)), NaN for a missing value.  Saved as
OUTPUTDIR/mobility/mobility.png.
"""

import argparse
import os

from PAOFLOW import GPAO

HERE = os.path.dirname(os.path.abspath(__file__))
OUTPUTDIR = os.path.join(HERE, 'output')
MOBILITY_DIR = os.path.join(OUTPUTDIR, 'mobility')


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument('--temperature', type=float, default=300.0,
                        help='temperature (K) of the rates panel')
    parser.add_argument('--experiment', default=None,
                        help='measured mobilities: T (K), electrons, holes (cm^2/Vs)')
    args = parser.parse_args()
    mobility = os.path.join(MOBILITY_DIR, 'mobility.dat')
    if not os.path.isfile(mobility):
        raise SystemExit('%s not found; run mobility.py first.' % mobility)
    scattering = os.path.join(MOBILITY_DIR, 'carrier_scattering.npz')
    GPAO.GPAO().plot_carrier_mobility(
        mobility, scattering if os.path.isfile(scattering) else None,
        temperature_k=args.temperature, experiment_file=args.experiment,
        filename=os.path.join(MOBILITY_DIR, 'mobility.png'),
    )


if __name__ == '__main__':
    main()
